TLM.f("Sancti/02-11",{"officium":"In Apparitione Beatæ Mariæ Virginis","rule":["ex C11;","Gloria","Credo","Prefatio=Maria=apparitióne"],"ruleInherited":["Gloria","Credo","Prefatio=Maria=Festivitate","Gloria","Suffr=Spiritu;Ecclesiæ,Papa;;","Prefatio=Maria=veneratione;"],"fallback":"Commune/C11","from":{"GradualeP":"Commune/C11"},"sections":{"Introitus":[{"k":"ref","la":"Apoc 21:2"},{"k":"text","la":"Vidi civitátem sanctam, Jerúsalem novam, descendéntem de cœlo a Deo, parátam sicut sponsam ornátam viro suo."},{"k":"ref","la":"Ps 44,2"},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea Regi."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Vidi civitátem sanctam, Jerúsalem novam, descendéntem de cœlo a Deo, parátam sicut sponsam ornátam viro suo."}],"Oratio":[{"k":"text","la":"Deus, qui per immaculátam Vírginis Conceptiónem dignum Filio tuo habitáculum præparásti: súpplices a te quǽsumus; ut, ejúsdem Vírginis Apparitiónem celebrántes, salútem mentis et córporis consequámur."},{"k":"macro","name":"Per eundem"}],"Lectio":[{"k":"text","la":"Léctio libri Apocalýpsis beáti Joánnis Apóstoli"},{"k":"ref","la":"Apoc 11:19; 12:1, 10"},{"k":"text","la":"Apértum est templum Dei in cœlo: et visa est arca testaménti ejus in templo ejus, et facta sunt fúlgura et voces et terræmótus et grando magna. Et signum magnum appáruit in cœlo: Múlier amícta sole, et luna sub pédibus ejus, et in cápite ejus coróna stellárum duódecim. Et audívi vocem magnam in cœlo dicéntem: Nunc facta est salus et virtus, et regnum Dei nostri et potéstas Christi ejus."}],"Graduale":[{"k":"ref","la":"Cant 2:12"},{"k":"text","la":"Flores apparuérunt in terra nostra, tempus putatiónis advénit, vox túrturis audíta est in terra nostra."},{"k":"ref","la":"Cant 2:10 et 14"},{"k":"text","la":"Surge, amíca mea, speciósa mea, et veni: colúmba mea in foramínibus petræ, in cavérna macériæ."},{"k":"text","la":"Allelúia, allelúia."},{"k":"text","la":"Osténde mihi fáciem tuam, sonet vox tua in áuribus meis: vox enim tua dulcis, et fácies tua decóra. Allelúia.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis"},{"k":"ref","la":"Luke 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Tractus":[{"k":"ref","la":"Cant 2:12"},{"k":"text","la":"Flores apparuérunt in terra nostra, tempus putatiónis advénit, vox túrturis audíta est in terra nostra."},{"k":"ref","la":"Cant 2:10 et 14"},{"k":"text","la":"Surge, amíca mea, speciósa mea, et veni: colúmba mea in foramínibus petræ, in cavérna macériæ."},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Judith 15:10"},{"k":"text","la":"Tu glória Jerúsalem, tu lætítia Israël, tu honorificéntia pópuli nostri."},{"k":"ref","la":"Cant 4:7"},{"k":"text","la":"Tota pulchra es, María: et mácula originális non est in te."},{"k":"text","la":"Felix es, sacra Virgo María, et omni laude digníssima, quæ serpéntis caput virgíneo pede contrivísti.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 1:26-31"},{"k":"text","la":"In illo témpore: Missus est Angelus Gábriel a Deo in civitátem Galilææ, cui nomen Názareth, ad Vírginem desponsátam viro, cui nomen erat Joseph, de domo David, et nomen Vírginis María. Et ingréssus Angelus ad eam dixit: Ave, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Quæ cum audísset, turbáta est in sermóne ejus: et cogitábat, qualis esset ista salutátio. Et ait Angelus ei: Ne tímeas, María, invenísti enim grátiam apud Deum: ecce, concípies in útero et páries fílium, et vocábis nomen ejus Jesum."}],"Offertorium":[{"k":"ref","la":"Luc 1:28"},{"k":"text","la":"Ave, grátia plena; Dóminus tecum: benedícta tu in muliéribus."}],"Secreta":[{"k":"text","la":"Hóstia laudis, quam tibi, Dómine, per mérita gloriósæ et immaculátæ Vírginis offérimus, sit tibi in odórem suavitátis, et nobis optátam cónferat córporis et ánimæ sanitátem."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 64:10"},{"k":"text","la":"Visitásti terram et inebriásti eam, multiplicásti locupletáre eam."}],"Postcommunio":[{"k":"text","la":"Quos cœlésti, Dómine, aliménto satiásti, súblevet dextera Genetrícis tuæ immaculátæ: ut ad ætérnam pátriam, ipsa adjuvánte, perveníre mereámur:"},{"k":"macro","name":"Qui vivis"}]},"hr":{"2d05f14ff4a22c51":{"t":"Otk 21, 2, Ps 44, 2\n(Otk 21, 2) Vidio sam sveti grad novi Jeruzalem gdje silazi od Boga s neba, pripravljen kao zaručnica ukrašena svojemu mužu. (Ps 44, 2) Iz srca mi navire radosna riječ, pripovijedam djela svoja Kralju.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Otk 21, 2) Vidio sam sveti grad novi Jeruzalem gdje silazi od Boga s neba, pripravljen kao zaručnica ukrašena svojemu mužu.","kn":"(Otkr. 21, 2). Vidio sam, sveti grad, novi Jeruzalem, gdje silazi od Boga s neba, pripravljen kao zaručnica ukrašena mužu svojemu. (Ps. 44, 2). Iz mog srca izvire divna pjesma: djela su moja namijenjena Kralju. Slava Ocu . . . Vidio sam . . .","knRef":"Kniewald 1942, str. 506–507 (snimka 254) (OCR)"},"82195479e5efe398":{"t":"<i>Pomolimo se</i>.\nBože, koji si bezgrješnim začećem Djevice pripravio dostojno prebivalište svome Sinu, molimo te, da slaveći ukazanje iste Djevice postignemo spasenje duše i tijela.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si bezgrješnim začećem Djevice pripravio dostojno prebivalište Sinu svojemu, molimo Te, da slaveći ukazanje iste Djevice postignemo spasenje duši i tijelu, po istom G. n.","knRef":"Kniewald 1942, str. 506–507 (snimka 254) (OCR)"},"eb8001d0ae121328":{"t":"Otk 11, 19; 12, 1 i 10\nČitanje knjige Otkrivenja bl. Ivana apostola. Otvorio se na nebu Božji hram, i u njegovu sam hramu vidio kovčeg njegova zavjeta. I nastao je bljesak i grmljavina i potresi i velika tuča. Na nebu se ukazao velik znak: Žena obučena u sunce i mjesec pod njezinim nogama, a na glavi joj vijenac od dvanaest zvijezda. I čuo sam gdje na nebu govori jaki glas: Došao je čas spasenja i pobjede i kraljevstva našega Boga i vlasti njegova Pomazanika.","kn":"Čitanje knjige Otkrivenja hl. Ivana apostola (11, 19, 12, 1. 10). I otvorio se na nebu Božji hram, i u njegovu sam hramu vidio kovčeg njegova zavjeta, i nastao je bljesak i grmljavina 1 potresi i velika tuča. Na nebu se ukazao velik znak: Žena obučena u sunce, i mjesec pod njezinim nogama, a na glavi joj vijenac od dvanaest zvijezda. I čuo sam, gdje na nebu govori jaki glas: Sada je nastao spas i sila i kraljevstvo našega Boga i vlast njegova Pomazanika.","knRef":"Kniewald 1942, str. 506–507 (snimka 254) (OCR)"},"e234c0af190f6ff3":{"kn":"(Pjes. 2, 12). Cvijeće se ukaza u zemlji našoj, vrijeme od rezanja stiže, glas grličin ču se u zemlji našoj. Ustani, prijateljice moja, ljepotice moja i hodi. Golubice moja u rasjeklinama kamenim, u zaklonu vrletnom.\nZavlaka (Judita 15, 10). Ti slavo Jeruzalema, ti radosti Izraela, ti diko naroda našega. Sva si lijepa, Marijo, i ljage istočne nije na Tebi. Blažena si, sveta Djevo Marijo, i svake hvale predostojna, jer si satrla zmijinu glavu djevičanskom nogom.","knRef":"Kniewald 1942, str. 507-508"},"558630ad906584b2":{"t":"Lk 1, 26-31\nSlijedi sveto Evanđelje po Luki. U ono vrijeme posla Bog anđela Gabrijela u galilejski grad Nazaret k djevici Mariji, koja je bila zaručena s Davidovim potomkom Josipom. Anđeo uđe k njoj i reče: Zdravo, milosti puna, Gospodin s tobom, blagoslovljena ti među ženama! Kad je ona to čula, uplaši se, i razmišljala je što taj pozdrav znači. Anđeo joj reče: Nemoj se bojati, Marijo, jer si našla milost u Boga: Evo, začet ćeš i roditi sina i dat ćeš mu ime Isus.","kn":"t Slijedi Sveto evanđelje po Luki (1, 26-31). U ono vrijeme posla Bog anđela Gabrijela’ u galilejski grad Nazaret k djevici zaručenoj s mužem, koji se zvao Josip iz kuće Davidove, ai djevica se zvala Manja. Kad je anđeo k njoj ušao, reče: Zdravo milosti^ puna, Gospodin s tobom, blagoslovljena ti među ženama! Kad je ona to čula, uplaši se na ove riječi i razmišljala je, što znači taj pozdrav. A anđeo joj reče; Ne boj se, Marijo, jer si našla milost kod Boga; evo, začet ćeš i roditi sina i dat ćeš mu ime Isus,","knRef":"Kniewald 1942, str. 508–509 (snimka 255) (OCR)"},"659d32582c023e8f":{"t":"Lk 1, 28\nZdravo milosti puna, Gospodin s tobom, blagoslovljena ti među ženama.","kn":"(Lk, 1, 28). Zdravo, milosti puna, Gospodin s Tobom, blagoslovljena Ti među ženama.","knRef":"Kniewald 1942, str. 508–509 (snimka 255) (OCR)"},"f553c785660aa37a":{"t":"Bila ti, Gospodine, ova žrtva hvale što je tebi prinosimo po zaslugama slavne i bezgrješne Djevice ugodna poput miomirisa, a nama udijelila željeno zdravlje duše i tijela.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bila Ti, Go.spodine, ova žrtva hvale, što je Tebi iprinosimo zasluga:ma slavne i neoskvrnjene Djevice, ugodna poput miomirisa, a nama udijelila željeno zdravlje duše i tijela po G. n.","knRef":"Kniewald 1942, str. 508–509 (snimka 255) (OCR)"},"a908da632a671b33":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože: i da te <i>o bezgrešnom začeću</i> blažene Marije vazda Djevice hvalimo, blagoslivljamo i slavimo. Ona je osjenjena Duhom Svetim začela jedinorođenoga Sina tvoga i sačuvavši slavu djevičanstva prosula svijetom vječno svjetlo Isusa Krista Gospodina našega. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, da uvijek i, svagdje Tebi, Gospodine sveti. Oče svemogući, vječni Bože, zahvaljujemo i da Te hvalimo, slavimo i uzvisujemo o (Pohodu, Prikazanju, Bezgrješnom Začeću, Navještenju, Uznesenju. Rođenju, svetkovini) blažene Marije, vazda Djevice, koja je po Duhu Svetom začela jedinorođenoga Tvoga Sina i zadržavši slavu djevičanstva dala svijetu vječno svijetlo, Isuisa Krista, Gospodina našega, po kome anđeli hvale Tvoje veličanstvo, klanjaju Ti se gospodstva, podlažu Ti se vlasti, slave Te nebesa i nebeske sile s blaženim Serafinima kličući u zajedničkoj^ radosti. A mi Te molimo, da nam zapovjediš s njima sjediniti naše glasove smjerno ispovijedajući:","knRef":"Kniewald 1942, str. 22–23 (snimka 12) (OCR)"},"72780dab208dba3b":{"t":"Ps 64, 10\nPohađaš zemlju i napajaš je, puniš je bogatstvom."},"67ee60ca604643ae":{"t":"<i>Pomolimo se</i>.\nDesnica tvoje bezgrješne Majke, Gospodine, tješila one koje si nahranio nebeskom hranom, da njezinom pomoću zavrijedimo doći u vječnu domovinu:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Desnica Tvoje neoskvrnjene Majke tješila one. Gospodine, koje si napitao nebeskom hranom; da njezinom pomoću zavrijedimo doći u vječnu domovinu, koji živiš . . .","knRef":"Kniewald 1942, str. 508–509 (snimka 255) (OCR)"},"0ab1ee988f0d7b2d":{"t":"Pj 2, 12 i 10 i 14\nCvijeće se pokazalo u zemlji našoj, vrijeme je pjevanja došlo, glas se grlice čuo u zemlji našoj. Ustani, prijateljice moja, lijepa moja, i dođi. Golubice moja, u pukotinama kamenim, u zaklonu vrletnom.\n\nPs 2, 7\n<i>Aleluja</i>, <i>aleluja</i>.\nPokaži mi svoje lice, neka odjekne tvoj glas u mojim ušima, jer je glas tvoj sladak i tvoje lice krasno. <i>Aleluja</i>.","kn":"(Pjes. 2, 12). Cvijeće se ukaza u zemlji našoj, vrijeme od rezanja stiže, glas grličin ču se u zemlji našoj. Ustam, prijateljice moja, ljepotice moja i hodi. Golubice poja u rasjeklinama kamenim, u zaklonu vrletnom.’\n\nAleluja, aleluja.^Pofeoži mi lice svoje, neko zaječi glas tvoj u ušima mojim:, jer je glas tvoj sladak i lice tvoje krasno, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 506–507 (snimka 254) (OCR)"}},"variants":{"paschal":{"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis."},{"k":"ref","la":"Luc 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}]}}});
